  await client.operations.execute({
    connection_id: 432,
    operation_key: 'navigate',
    input: { tab_id: 1949384116, url: href.output.value, open_in_new_tab: false, wait_for_load: true }
  });
  await ctx.sleep(10000);
  const drained = await client.operations.execute({
    connection_id: 432,
    operation_key: 'network_intercept_drain',
    input: { session_id: started.output.session_id }
  });
  const fingerprint = (text) => {
    let hash = 2166136261;
    for (let i = 0; i < text.length; i += 1) {
      hash ^= text.charCodeAt(i);
      hash = Math.imul(hash, 16777619);
    }
    return (hash >>> 0).toString(16).padStart(8, '0');
  };
  return {
    session_id: started.output.session_id,
    responses: (drained.output.responses ?? []).map((response) => ({
      url: response.url,
      status: response.status,
      truncated: response.truncated,
      body_length: response.body?.length ?? 0,
      fingerprint: response.body ? fingerprint(response.body) : null
    }))
  };
}`});
