import { readFile } from "node:fs/promises";

const url = "https://app.lobu.ai/mcp";
const store = JSON.parse(await readFile(process.env.HOME + "/.mcp-inspector/storage/oauth.json", "utf8"));
const server = store.servers?.[url];
const issuer = server?.activeIssuer;
const accessToken = issuer ? server?.byIssuer?.[issuer]?.tokens?.access_token : undefined;
if (!accessToken) throw new Error("No stored production OAuth token");

const baseHeaders = {
  authorization: "Bearer " + accessToken,
  accept: "application/json, text/event-stream",
  "content-type": "application/json",
};
async function post(body, sessionId) {
  const headers = { ...baseHeaders };
  if (sessionId) {
    headers["mcp-session-id"] = sessionId;
    headers["mcp-protocol-version"] = "2025-11-25";
  }
  const response = await fetch(url, {
    method: "POST",
    headers,
    body: JSON.stringify(body),
  });
  const text = await response.text();
  const json = text ? JSON.parse(text) : null;
  return { response, json };
}

const init = await post({
  jsonrpc: "2.0",
  id: 1,
  method: "initialize",
  params: {
    protocolVersion: "2025-11-25",
    capabilities: {
      extensions: {
        "io.modelcontextprotocol/ui": {
          mimeTypes: ["text/html;profile=mcp-app"],
        },
      },
    },
    clientInfo: { name: "lobu-production-approval-e2e", version: "1.0.0" },
  },
});
const sessionId = init.response.headers.get("mcp-session-id");
if (init.response.status !== 200 || !sessionId) throw new Error("Initialize failed");

await post({
  jsonrpc: "2.0",
  method: "notifications/initialized",
}, sessionId);

const getBefore = await post({
  jsonrpc: "2.0",
  id: 2,
  method: "tools/call",
  params: {
    name: "get_approval",
    arguments: { run_id: 1009979 },
  },
}, sessionId);
const before = getBefore.json?.result;
const beforeTitle = before?.structuredContent?.title;
const beforeActions = before?.structuredContent?.actions ?? [];
const capability = before?._meta?.["lobu/approval-capability"];
const pending = typeof capability === "string" && capability.length > 0 && beforeActions.length > 0;

let resolveResult = null;
if (pending) {
  const resolved = await post({
    jsonrpc: "2.0",
    id: 3,
    method: "tools/call",
    params: {
      name: "resolve_approval",
      arguments: {
        run_id: 1009979,
        decision: "approve",
        input: {
          environment: "Staging",
          note: "production Inspector v41 E2E",
        },
      },
      _meta: {
        "lobu/approval-capability": capability,
      },
    },
  }, sessionId);
  resolveResult = {
    status: resolved.response.status,
    isError: resolved.json?.result?.isError ?? false,
    text: resolved.json?.result?.content?.[0]?.text ?? null,
  };
}

const getAfter = await post({
  jsonrpc: "2.0",
  id: 4,
  method: "tools/call",
  params: {
    name: "get_approval",
    arguments: { run_id: 1009979 },
  },
}, sessionId);
const after = getAfter.json?.result;
console.log(JSON.stringify({
  initializeStatus: init.response.status,
  before: {
    title: beforeTitle,
    actionCount: beforeActions.length,
    pending,
  },
  resolve: resolveResult,
  after: {
    title: after?.structuredContent?.title ?? null,
    actionCount: after?.structuredContent?.actions?.length ?? null,
    initialValues: after?.structuredContent?.blocks?.[0]?.initialValues ?? null,
    outputTemplate: after?._meta?.["openai/outputTemplate"] ?? null,
    memberRole: after?._meta?.["lobu/member-role"] ?? null,
  },
}));
`;
